    CREATE TABLE "TeamGoals" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "BusinessUnitId" bigint NOT NULL,
        "GoalText" character varying(1000) NOT NULL,
        "DisplayOrder" smallint NOT NULL,
        "TargetDate" date,
