        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "CreatedBy" integer,
        CONSTRAINT "PK_TeamGoals" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_TeamGoals_BusinessUnits_BusinessUnitId" FOREIGN KEY ("BusinessUnitId") REFERENCES "BusinessUnits" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

