DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260824140040_AddTeamQuestions') THEN
    PERFORM setval(
        pg_get_serial_sequence('"TeamQuestionAttributionTypes"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "TeamQuestionAttributionTypes") + 1,
            nextval(pg_get_serial_sequence('"TeamQuestionAttributionTypes"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"TeamQuestionMainCategories"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "TeamQuestionMainCategories") + 1,
            nextval(pg_get_serial_sequence('"TeamQuestionMainCategories"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"TeamQuestionSamplingModes"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "TeamQuestionSamplingModes") + 1,
            nextval(pg_get_serial_sequence('"TeamQuestionSamplingModes"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"TeamStateIndicators"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "TeamStateIndicators") + 1,
            nextval(pg_get_serial_sequence('"TeamStateIndicators"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"TeamQuestionSubCategories"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "TeamQuestionSubCategories") + 1,
            nextval(pg_get_serial_sequence('"TeamQuestionSubCategories"', 'Id'))),
        false);
    END IF;
END $EF$;

